import { readFile, writeFile } from "node:fs/promises";
import { loadGuideInventory } from "../lib/guides/guide-loader.mjs";

const outputIndex = process.argv.indexOf("--output");
const artifactUrl = outputIndex >= 0
  ? new URL(process.argv[outputIndex + 1], new URL("../", import.meta.url))
  : new URL("../lib/guides/guide-runtime-inventory.generated.mjs", import.meta.url);
const checkOnly = process.argv.includes("--check");

function renderModule(inventory) {
  return [
    "// Generated by scripts/generate-guide-runtime-inventory.mjs. Do not edit.",
    `export const guideRuntimeInventory = ${JSON.stringify(inventory, null, 2)};`,
    ""
  ].join("\n");
}

const expected = renderModule(await loadGuideInventory());

if (checkOnly) {
  const actual = await readFile(artifactUrl, "utf8").catch(() => "");
  if (actual !== expected) {
    console.error("Guide runtime inventory is stale. Run npm run generate:guide-runtime.");
    process.exitCode = 1;
  } else {
    console.log("Guide runtime inventory is current.");
  }
} else {
  await writeFile(artifactUrl, expected, "utf8");
  console.log("Generated Guide runtime inventory.");
}
